# -*- coding: utf-8 -*-
"""Patch par remplacements (28/11/2026, 3e passe) : vente totale d une unite de
compte soumise aux frais trimestriels. Si une vente laisse un reliquat inferieur
a 1 % de la position d avant la vente (ecart entre frais calcules et frais reels),
le reliquat est solde par un mouvement virtuel : la ligne vendue ne reapparait
pas sur la page. Les frais sont desormais calcules en rejouant le journal dans
l ordre des dates. index.html (ajouterFrais) et supports.py (frais_trimestriels)
restent identiques.
Applique par le workflow patch.yml ; chaque texte doit etre trouve une seule fois,
sinon aucun fichier n est ecrit."""
import sys

PATCHS = {
"index.html": [
('// Frais de gestion des unites de compte (champ frais de supports.txt, en % par\n// trimestre) : l assureur les preleve en diminuant le nombre de parts. On cree\n// un mouvement virtuel au dernier jour de chaque trimestre echu, egal aux parts\n// detenues ce jour-la x taux, sans prix : la quantite baisse, le PRU ne bouge\n// pas, et ce n est pas un retrait (investiA l ignore), donc c est une perte.\n// Meme calcul que supports.frais_trimestriels() cote Python.\nfunction ajouterFrais(){\n  const auj=todayStr();\n  SUPPORTS.forEach(function(s){\n    if(!s.frais) return;\n    const f=s.frais/100;\n    const mv=APPORTS.filter(function(a){ return a.cle===s.cle; });\n    const dates=mv.map(function(a){ return a.date; }).filter(Boolean).sort();\n    if(!dates.length) return;\n    const fins=["-03-31","-06-30","-09-30","-12-31"];\n    const prel=[];\n    for(let an=parseInt(dates[0].slice(0,4),10); an<=parseInt(auj.slice(0,4),10); an++){\n      for(let i=0;i<4;i++){\n        const d=an+fins[i];\n        if(d<dates[0] || d>auj) continue;\n        let det=0;\n        mv.forEach(function(a){ if(!a.date || a.date<=d) det+=a.qte; });\n        prel.forEach(function(x){ det+=x.qte; });\n        if(det>1e-6) prel.push({date:d, nom:s.nom, cle:s.cle, qte:-det*f, prix:null, frais:true});\n      }\n    }\n    prel.forEach(function(x){ APPORTS.push(x); QUANTITES[s.cle]=(QUANTITES[s.cle]||0)+x.qte; });\n    if(Math.abs(QUANTITES[s.cle]||0)<1e-6) QUANTITES[s.cle]=0;\n  });\n}\n\n',
 '// Frais de gestion des unites de compte (champ frais de supports.txt, en % par\n// trimestre) : l assureur les preleve en diminuant le nombre de parts. On rejoue\n// le journal du support dans l ordre des dates et, au dernier jour de chaque\n// trimestre echu, on cree un mouvement virtuel egal aux parts detenues ce\n// jour-la x taux, sans prix : la quantite baisse, le PRU ne bouge pas, et ce\n// n est pas un retrait (investiA l ignore), donc c est une perte.\n// Vente totale : si une vente laisse un reliquat inferieur a 1 % de la position\n// d avant la vente, c est un ecart entre frais calcules et frais reels ; il est\n// solde par un mouvement virtuel, et la ligne vendue disparait bien de la page.\n// Meme calcul que supports.frais_trimestriels() cote Python.\nfunction ajouterFrais(){\n  const auj=todayStr();\n  const fins=["-03-31","-06-30","-09-30","-12-31"];\n  SUPPORTS.forEach(function(s){\n    if(!s.frais) return;\n    const f=s.frais/100;\n    const mv=APPORTS.filter(function(a){ return a.cle===s.cle; });\n    const dates=mv.map(function(a){ return a.date; }).filter(Boolean).sort();\n    if(!dates.length) return;\n    let det=0;\n    mv.forEach(function(a){ if(!a.date) det+=a.qte; });\n    const jours={};\n    dates.forEach(function(d){ jours[d]=1; });\n    for(let an=parseInt(dates[0].slice(0,4),10); an<=parseInt(auj.slice(0,4),10); an++){\n      fins.forEach(function(x){ const d=an+x; if(d>=dates[0] && d<=auj) jours[d]=1; });\n    }\n    const virt=[];\n    Object.keys(jours).sort().forEach(function(d){\n      const avant=det; let vente=false;\n      mv.forEach(function(a){ if(a.date===d){ det+=a.qte; if(a.qte<0) vente=true; } });\n      if(vente && det!==0 && avant>0 && Math.abs(det)<=0.01*avant){\n        virt.push({date:d, nom:s.nom, cle:s.cle, qte:-det, prix:null, frais:true});\n        det=0;\n      }\n      if(fins.indexOf(d.slice(4))>=0 && det>1e-6){\n        virt.push({date:d, nom:s.nom, cle:s.cle, qte:-det*f, prix:null, frais:true});\n        det-=det*f;\n      }\n    });\n    virt.forEach(function(x){ APPORTS.push(x); QUANTITES[s.cle]=(QUANTITES[s.cle]||0)+x.qte; });\n    if(Math.abs(QUANTITES[s.cle]||0)<1e-6) QUANTITES[s.cle]=0;\n  });\n}\n\n'),
],
"supports.py": [
('# ----------------------------------------------------------------------------\n#  FRAIS DE GESTION DES UNITES DE COMPTE (assurance vie)\n# ----------------------------------------------------------------------------\n#  L assureur preleve chaque trimestre un pourcentage des parts detenues, en\n#  diminuant leur nombre. On reconstitue ces prelevements au dernier jour de\n#  chaque trimestre echu : parts detenues ce jour-la (mouvements dates de ce jour\n#  inclus, prelevements precedents deduits) x taux. Meme calcul que index.html.\nFINS_TRIMESTRE = ("-03-31", "-06-30", "-09-30", "-12-31")\n\n\ndef frais_trimestriels(taux_pct, mouvements, jusqua):\n    """mouvements : [(date AAAA-MM-JJ, quantite), ...] d un seul support.\n    Renvoie les prelevements [(date, quantite negative), ...] jusqu a jusqua inclus."""\n    if not taux_pct or not mouvements:\n        return []\n    f = taux_pct / 100.0\n    dates = sorted(d for d, _ in mouvements if d)\n    if not dates:\n        return []\n    out = []\n    for annee in range(int(dates[0][:4]), int(jusqua[:4]) + 1):\n        for fin in FINS_TRIMESTRE:\n            d = "%d%s" % (annee, fin)\n            if d < dates[0]:\n                continue\n            if d > jusqua:\n                return out\n            detenu = sum(q for dm, q in mouvements if not dm or dm <= d)\n            detenu += sum(q for _, q in out)\n            if detenu > 1e-6:\n                out.append((d, -detenu * f))\n    return out\n\n\n',
 '# ----------------------------------------------------------------------------\n#  FRAIS DE GESTION DES UNITES DE COMPTE (assurance vie)\n# ----------------------------------------------------------------------------\n#  L assureur preleve chaque trimestre un pourcentage des parts detenues, en\n#  diminuant leur nombre. On rejoue le journal du support dans l ordre des dates\n#  et, au dernier jour de chaque trimestre echu, on preleve parts detenues ce\n#  jour-la (mouvements dates de ce jour inclus) x taux.\n#  Vente totale : si une vente laisse un reliquat inferieur a 1 % de la position\n#  d avant la vente, c est un ecart entre frais calcules et frais reels ; il est\n#  solde par un mouvement virtuel. Meme calcul que ajouterFrais() dans index.html.\nFINS_TRIMESTRE = ("-03-31", "-06-30", "-09-30", "-12-31")\n\n\ndef frais_trimestriels(taux_pct, mouvements, jusqua):\n    """mouvements : [(date AAAA-MM-JJ, quantite), ...] d un seul support.\n    Renvoie les mouvements virtuels [(date, quantite), ...] jusqu a jusqua inclus :\n    prelevements de frais et soldes de reliquat apres une vente totale."""\n    if not taux_pct or not mouvements:\n        return []\n    f = taux_pct / 100.0\n    dates = sorted(d for d, _ in mouvements if d)\n    if not dates:\n        return []\n    detenu = sum(q for d, q in mouvements if not d)\n    jours = set(dates)\n    for annee in range(int(dates[0][:4]), int(jusqua[:4]) + 1):\n        for fin in FINS_TRIMESTRE:\n            d = "%d%s" % (annee, fin)\n            if dates[0] <= d <= jusqua:\n                jours.add(d)\n    out = []\n    for d in sorted(jours):\n        avant, vente = detenu, False\n        for dm, q in mouvements:\n            if dm == d:\n                detenu += q\n                vente = vente or q < 0\n        if vente and detenu != 0 and avant > 0 and abs(detenu) <= 0.01 * avant:\n            out.append((d, -detenu))\n            detenu = 0.0\n        if d[4:] in FINS_TRIMESTRE and detenu > 1e-6:\n            out.append((d, -detenu * f))\n            detenu -= detenu * f\n    return out\n\n\n'),
],
}

nouveaux = {}
for fichier, remplacements in PATCHS.items():
    s = open(fichier, encoding="utf-8").read()
    for ancien, nouveau in remplacements:
        n = s.count(ancien)
        if n != 1:
            print("ECHEC %s : texte trouve %d fois : %r" % (fichier, n, ancien[:80]))
            sys.exit(1)
        s = s.replace(ancien, nouveau)
    nouveaux[fichier] = s
for fichier, s in nouveaux.items():
    open(fichier, "w", encoding="utf-8").write(s)
    print("%s : patch applique" % fichier)
